script:
frappe.ui.form.on('BOM Item', {
    custom_operation_instruction: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.custom_operation_instruction) {
            frappe.model.set_value(cdt, cdn, 'custom_operation_instruction_marathi', '');
            return;
        }

        let url = "https://api.mymemory.translated.net/get?q="
            + encodeURIComponent(row.custom_operation_instruction)
            + "&langpair=en|mr";

        fetch(url)
            .then(response => response.json())
            .then(data => {
                let translated = data.responseData.translatedText || '';
                frappe.model.set_value(cdt, cdn, 'custom_operation_instruction_marathi', translated)
                    .then(() => {
                        // Show the translation immediately, without the user having to
                        // click into the Marathi cell to force a re-render.
                        let grid = frm.fields_dict.items && frm.fields_dict.items.grid;
                        if (!grid) return;
                        let grid_row = grid.grid_rows_by_docname && grid.grid_rows_by_docname[cdn];
                        if (grid_row && grid_row.refresh_field) {
                            grid_row.refresh_field('custom_operation_instruction_marathi');
                        } else {
                            grid.refresh();
                        }
                    });
            })
            .catch(err => {
                console.error("Translation error:", err);
            });
    }
});
